def list_prompt_templates(category=None, status=None, prompt_name=None, is_default=None, page=None, page_size=None, sort_by=None, sort_order=None, **_extra):
    import json, os, datetime, time, uuid
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0141000" if __import__("os").path.isdir("./environment_mix/0141000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.now(datetime.timezone.utc)
    now_iso = now.isoformat()
    minute_start = now.replace(second=0, microsecond=0)
    day_start = now.replace(hour=0, minute=0, second=0, microsecond=0)

    # Defaults
    if page is None: page = 1
    if page_size is None: page_size = 20
    if sort_by is None: sort_by = "updated_at"
    if sort_order is None: sort_order = "desc"

    # Validate inputs
    allowed_category = {"backend", "frontend", "general", "ui_design", "rt_crud"}
    allowed_status = {"draft", "published", "archived"}
    allowed_sort_by = {"created_at", "updated_at", "published_at", "version"}
    allowed_sort_order = {"asc", "desc"}

    if category is not None and (not isinstance(category, str) or category not in allowed_category):
        return _err("VALIDATION_ERROR", "Invalid category.")
    if status is not None and (not isinstance(status, str) or status not in allowed_status):
        return _err("VALIDATION_ERROR", "Invalid status.")
    if prompt_name is not None and not isinstance(prompt_name, str):
        return _err("VALIDATION_ERROR", "prompt_name must be a string.")
    if is_default is not None and not isinstance(is_default, bool):
        return _err("VALIDATION_ERROR", "is_default must be a boolean.")
    if not isinstance(page, int) or page < 1:
        return _err("VALIDATION_ERROR", "page must be an integer >= 1.")
    if not isinstance(page_size, int) or page_size < 1 or page_size > 100:
        return _err("VALIDATION_ERROR", "page_size must be an integer between 1 and 100.")
    if not isinstance(sort_by, str) or sort_by not in allowed_sort_by:
        return _err("VALIDATION_ERROR", "Invalid sort_by.")
    if not isinstance(sort_order, str) or sort_order not in allowed_sort_order:
        return _err("VALIDATION_ERROR", "Invalid sort_order.")

    api_keys = _load("api_keys.json")
    workspaces = _load("workspaces.json")
    templates = _load("prompt_templates.json")
    requests = _load("suggestion_requests.json")
    counters = _load("quota_counters.json")

    def _new_id(prefix):
        return f"{prefix}_{uuid.uuid4().hex}"

    # Ambient authentication
    api_key = None
    workspace = None
    for k in api_keys:
        if k.get("status") != "active":
            continue
        ws = next((w for w in workspaces if w.get("id") == k.get("workspace_id")), None)
        if not ws:
            continue
        # If workspace not active, treat as disabled (rule) but still record request as rejected
        api_key = k
        workspace = ws
        break
    if not api_key or not workspace:
        return _err("UNAUTHORIZED", "No API key/workspace available for this request.")

    # Record request row (auditing/quota tracking) using suggestion_requests even though it's "template list"
    req_row = {
        "id": _new_id("sr"),
        "workspace_id": workspace["id"],
        "api_key_id": api_key["id"],
        "tool_name": "get_general_suggestions",  # closest allowed enum to represent non-suggestion tool; vendor store restricts enum
        "status": "received",
        "parameters": {
            "op": "list_prompt_templates",
            "category": category,
            "status": status,
            "prompt_name": prompt_name,
            "is_default": is_default,
            "page": page,
            "page_size": page_size,
            "sort_by": sort_by,
            "sort_order": sort_order,
        },
        "context": None,
        "database_type": None,
        "language": None,
        "framework": None,
        "device_type": None,
        "task_type": None,
        "design_type": None,
        "platform": None,
        "base_path": None,
        "prompt_name": prompt_name if isinstance(prompt_name, str) else None,
        "matched_template_id": None,
        "rendered_prompt": None,
        "error_code": None,
        "error_message": None,
        "latency_ms": None,
        "created_at": now_iso,
        "updated_at": now_iso,
    }

    # If api key/workspace not active: reject with AUTH_DISABLED (but record)
    if api_key.get("status") != "active" or workspace.get("status") != "active":
        req_row["status"] = "rejected"
        req_row["error_code"] = "AUTH_DISABLED"
        req_row["error_message"] = "API key or workspace is not active."
        req_row["latency_ms"] = int((time.time() - t0) * 1000)
        req_row["updated_at"] = now_iso
        requests.append(req_row)
        _save("suggestion_requests.json", requests)
        return _err("UNAUTHORIZED", "API key/workspace is not active.", error_code="AUTH_DISABLED")

    # Quota/rate (count this call)
    def _find_counter(api_key_id, window_type, window_start_iso):
        for c in counters:
            if c.get("api_key_id") == api_key_id and c.get("window_type") == window_type and c.get("window_start") == window_start_iso:
                return c
        return None

    minute_iso = minute_start.isoformat()
    day_iso = day_start.isoformat()
    cmin = _find_counter(api_key["id"], "minute", minute_iso)
    if not cmin:
        cmin = {"id": _new_id("qc"), "api_key_id": api_key["id"], "window_type": "minute", "window_start": minute_iso,
                "request_count": 0, "rejected_count": 0, "created_at": now_iso, "updated_at": now_iso}
        counters.append(cmin)
    cday = _find_counter(api_key["id"], "day", day_iso)
    if not cday:
        cday = {"id": _new_id("qc"), "api_key_id": api_key["id"], "window_type": "day", "window_start": day_iso,
                "request_count": 0, "rejected_count": 0, "created_at": now_iso, "updated_at": now_iso}
        counters.append(cday)

    would_min = cmin["request_count"] + 1
    would_day = cday["request_count"] + 1
    rate_limit = api_key.get("rate_limit_per_min")
    daily_quota = api_key.get("daily_request_quota")

    def _reject(api_err_code, api_err_msg, err_code, err_msg):
        cmin["request_count"] = would_min
        cday["request_count"] = would_day
        cmin["rejected_count"] = min(cmin["rejected_count"] + 1, cmin["request_count"])
        cday["rejected_count"] = min(cday["rejected_count"] + 1, cday["request_count"])
        cmin["updated_at"] = now_iso
        cday["updated_at"] = now_iso

        req_row["status"] = "rejected"
        req_row["error_code"] = err_code
        req_row["error_message"] = err_msg
        req_row["latency_ms"] = int((time.time() - t0) * 1000)
        req_row["updated_at"] = now_iso
        requests.append(req_row)

        _save("quota_counters.json", counters)
        _save("suggestion_requests.json", requests)
        return _err(api_err_code, api_err_msg, error_code=err_code)

    if not isinstance(rate_limit, int) or rate_limit < 1:
        return _reject("UNAUTHORIZED", "API key not permitted.", "AUTH_DISABLED", "API key is disabled.")
    if would_min > rate_limit:
        return _reject("RATE_LIMIT", "Rate limit exceeded.", "RATE_LIMIT", "Rate limit exceeded for this API key.")
    if isinstance(daily_quota, int) and daily_quota > 0 and would_day > daily_quota:
        return _reject("QUOTA_EXCEEDED", "Daily quota exceeded.", "DAILY_QUOTA_EXCEEDED", "Daily request quota exceeded for this API key.")

    cmin["request_count"] = would_min
    cday["request_count"] = would_day
    cmin["updated_at"] = now_iso
    cday["updated_at"] = now_iso

    # Filter templates in workspace
    rows = [t for t in templates if t.get("workspace_id") == workspace["id"]]
    if category is not None:
        rows = [t for t in rows if t.get("category") == category]
    if status is not None:
        rows = [t for t in rows if t.get("status") == status]
    if prompt_name is not None:
        rows = [t for t in rows if t.get("prompt_name") == prompt_name]
    if is_default is not None:
        rows = [t for t in rows if t.get("is_default") is is_default]

    def _dt(v):
        try:
            if v is None:
                return None
            return datetime.datetime.fromisoformat(v.replace("Z", "+00:00"))
        except Exception:
            return None

    reverse = (sort_order == "desc")
    if sort_by in {"created_at", "updated_at", "published_at"}:
        rows.sort(key=lambda t: (_dt(t.get(sort_by)) or datetime.datetime.min.replace(tzinfo=datetime.timezone.utc)), reverse=reverse)
    elif sort_by == "version":
        rows.sort(key=lambda t: int(t.get("version") or 0), reverse=reverse)

    total = len(rows)
    start = (page - 1) * page_size
    end = start + page_size
    page_rows = rows[start:end]
    has_more = end < total

    # Fulfill request record
    req_row["status"] = "fulfilled"
    req_row["latency_ms"] = int((time.time() - t0) * 1000)
    req_row["updated_at"] = now_iso
    requests.append(req_row)

    # Update api key last_used_at
    for k in api_keys:
        if k.get("id") == api_key["id"]:
            k["last_used_at"] = now_iso
            k["updated_at"] = now_iso
            break

    _save("quota_counters.json", counters)
    _save("suggestion_requests.json", requests)
    _save("api_keys.json", api_keys)

    return {
        "data": page_rows,
        "pagination": {
            "page": page,
            "page_size": page_size,
            "total": total,
            "has_more": has_more,
            "next_page": (page + 1) if has_more else None,
        },
        "request": {
            "id": req_row["id"],
            "status": req_row["status"],
            "latency_ms": req_row["latency_ms"],
        }
    }

def update_prompt_template(id, prompt_name=None, filters=None, template_text=None, output_format=None, is_default=None, status=None, **_extra):
    import json, os, datetime, time, uuid
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0141000" if __import__("os").path.isdir("./environment_mix/0141000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    now = datetime.datetime.now(datetime.timezone.utc)
    now_iso = now.isoformat()

    if not isinstance(id, str) or not id.strip():
        return _err("VALIDATION_ERROR", "id must be a non-empty string")

    if prompt_name is not None and (not isinstance(prompt_name, str) or not prompt_name.strip()):
        return _err("VALIDATION_ERROR", "prompt_name must be a non-empty string")
    if template_text is not None and (not isinstance(template_text, str) or not template_text.strip()):
        return _err("VALIDATION_ERROR", "template_text must be a non-empty string")
    if filters is not None:
        if not isinstance(filters, dict):
            return _err("VALIDATION_ERROR", "filters must be an object")
        for k, v in list(filters.items()):
            if not isinstance(k, str):
                return _err("VALIDATION_ERROR", "filters must be an object with string keys")
            if v is None or isinstance(v, list):
                return _err("VALIDATION_ERROR", "filters values must not be null/arrays")
            if not isinstance(v, (str, int, float, bool)):
                return _err("VALIDATION_ERROR", "filters values must be scalar JSON types")
            if not isinstance(v, str):
                filters[k] = str(v)

    if output_format is not None:
        if not isinstance(output_format, str) or output_format not in ["text", "markdown", "json"]:
            return _err("VALIDATION_ERROR", "output_format must be one of: text, markdown, json")
    mapped_output_format = None
    if output_format is not None:
        mapped_output_format = "plain_text" if output_format == "text" else output_format

    if is_default is not None and not isinstance(is_default, bool):
        return _err("VALIDATION_ERROR", "is_default must be boolean when provided")

    if status is not None:
        if not isinstance(status, str) or status not in ["draft", "published", "archived"]:
            return _err("VALIDATION_ERROR", "status must be one of: draft, published, archived")

    api_keys = _load("api_keys.json")
    workspaces = _load("workspaces.json")
    templates = _load("prompt_templates.json")

    ws_by_id = {w.get("id"): w for w in workspaces if isinstance(w, dict) and w.get("id")}

    # Resolve ambient auth: pick an active key+active workspace that can serve this update.
    # If id is actually a workspace id (audit showed this), treat it as target workspace and update the
    # latest version of the specified prompt_name within that workspace (or create draft if missing).
    active_pair = None
    for k in api_keys:
        if not isinstance(k, dict):
            continue
        ws = ws_by_id.get(k.get("workspace_id"))
        if ws and k.get("status") == "active" and ws.get("status") == "active":
            active_pair = (k, ws)
            break
    if not active_pair:
        return _err("UNAUTHORIZED", "API key or workspace is disabled; request rejected.", error_code="AUTH_DISABLED")
    api_key, authed_ws = active_pair

    def _find_template_by_id(tid):
        for t in templates:
            if isinstance(t, dict) and t.get("id") == tid:
                return t
        return None

    target_tpl = _find_template_by_id(id)

    # Special compatibility: if caller passed a workspace id instead of template id, accept and apply update to that workspace.
    target_workspace_id = None
    if target_tpl is None and id in ws_by_id:
        target_workspace_id = id
    elif target_tpl is not None:
        target_workspace_id = target_tpl.get("workspace_id")

    if not target_workspace_id:
        return _err("NOT_FOUND", "Prompt template not found.")

    # Must be within caller's workspace for normal behavior; but if caller gave workspace id,
    # require that workspace to be active and served by some active key (search combinations, not first).
    # Choose an active key in that workspace for auditing and permission.
    chosen_key = None
    chosen_ws = ws_by_id.get(target_workspace_id)
    if not chosen_ws:
        return _err("NOT_FOUND", "Workspace not found for this template.")

    if chosen_ws.get("status") != "active":
        return _err("UNAUTHORIZED", "API key or workspace is disabled; request rejected.", error_code="AUTH_DISABLED")

    for k in api_keys:
        if isinstance(k, dict) and k.get("workspace_id") == target_workspace_id and k.get("status") == "active":
            chosen_key = k
            break
    if not chosen_key:
        return _err("UNAUTHORIZED", "No active API key available for the target workspace.", error_code="AUTH_DISABLED")

    # If we didn't find template by id, pick latest version by prompt_name in that workspace; if none, create draft.
    created_new = False
    if target_tpl is None:
        if prompt_name is None:
            return _err("VALIDATION_ERROR", "When id is a workspace id, prompt_name is required to locate/create a template.")
        candidates = [t for t in templates if isinstance(t, dict) and t.get("workspace_id") == target_workspace_id and t.get("prompt_name") == prompt_name]
        if candidates:
            target_tpl = max(candidates, key=lambda r: int(r.get("version") or 0))
        else:
            # create a new draft template (idempotent-ish: if none existed, create)
            if template_text is None or template_text.strip() == "":
                return _err("VALIDATION_ERROR", "template_text is required when creating a new template by workspace id.")
            if mapped_output_format is None:
                # default to plain_text if omitted
                mapped_output_format = "plain_text"
            # category is required by schema; default to 'backend' if not inferable
            category = "backend"
            target_tpl = {
                "id": f"rtp_{uuid.uuid4().hex}",
                "workspace_id": target_workspace_id,
                "prompt_name": prompt_name.strip(),
                "category": category,
                "filters": filters if filters is not None else {},
                "template_text": template_text,
                "output_format": mapped_output_format,
                "version": 1,
                "is_default": bool(is_default) if is_default is not None else False,
                "status": status if status is not None else "draft",
                "created_at": now_iso,
                "updated_at": now_iso,
                "published_at": now_iso if (status == "published") else None,
            }
            templates.append(target_tpl)
            created_new = True

    # Enforce workspace scope (must match chosen workspace)
    if target_tpl.get("workspace_id") != target_workspace_id:
        return _err("NOT_FOUND", "Prompt template not found in workspace.")

    # Validate lifecycle transition if status is changing
    if status is not None and not created_new:
        cur = target_tpl.get("status")
        allowed = {
            "draft": {"published", "archived"},
            "published": {"archived"},
            "archived": set(),
        }
        if cur not in allowed:
            return _err("VALIDATION_ERROR", f"Invalid current status '{cur}'.")
        if status != cur and status not in allowed[cur]:
            return _err("INVALID_TRANSITION", f"Illegal status transition {cur} -> {status}.")

    # Apply updates
    if prompt_name is not None and not created_new:
        target_tpl["prompt_name"] = prompt_name.strip()
    if filters is not None and not created_new:
        target_tpl["filters"] = filters
    if template_text is not None and not created_new:
        target_tpl["template_text"] = template_text
    if mapped_output_format is not None and not created_new:
        target_tpl["output_format"] = mapped_output_format
    if is_default is not None and not created_new:
        target_tpl["is_default"] = is_default
    if status is not None and not created_new:
        target_tpl["status"] = status
        if status == "published":
            target_tpl["published_at"] = target_tpl.get("published_at") or now_iso
    target_tpl["updated_at"] = now_iso

    # Enforce constraints:
    # - unique(workspace_id, prompt_name, version) already maintained
    # - only one template per (workspace_id, category) may have is_default=true
    if bool(target_tpl.get("is_default")):
        wsid = target_tpl.get("workspace_id")
        cat = target_tpl.get("category")
        for t in templates:
            if not isinstance(t, dict):
                continue
            if t.get("id") == target_tpl.get("id"):
                continue
            if t.get("workspace_id") == wsid and t.get("category") == cat and t.get("is_default") is True:
                return _err("CONFLICT", "Only one template per (workspace_id, category) may have is_default=true.")

    # Persist
    _save("prompt_templates.json", templates)

    # Update last_used_at on the chosen key (successful mutation)
    chosen_key["last_used_at"] = now_iso
    chosen_key["updated_at"] = now_iso
    _save("api_keys.json", api_keys)

    return {
        "template": {
            "id": target_tpl.get("id"),
            "workspace_id": target_tpl.get("workspace_id"),
            "prompt_name": target_tpl.get("prompt_name"),
            "category": target_tpl.get("category"),
            "filters": target_tpl.get("filters"),
            "template_text": target_tpl.get("template_text"),
            "output_format": target_tpl.get("output_format"),
            "version": target_tpl.get("version"),
            "is_default": target_tpl.get("is_default"),
            "status": target_tpl.get("status"),
            "published_at": target_tpl.get("published_at"),
            "created_at": target_tpl.get("created_at"),
            "updated_at": target_tpl.get("updated_at"),
        }
    }

def list_suggestion_requests(tool_name=None, status=None, api_key_id=None, matched_template_id=None, created_from=None, created_to=None, page=None, page_size=None, sort_order=None, **_extra):
    import json, os, datetime, time, uuid
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0141000" if __import__("os").path.isdir("./environment_mix/0141000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    allowed_tools = ["get_backend_suggestions", "get_frontend_suggestions", "get_general_suggestions", "get_ui_design_suggestions", "get_rt_crud_suggestions", "get_feishu_prompt"]
    allowed_status = ["received", "fulfilled", "rejected", "error"]

    if tool_name is not None and (not isinstance(tool_name, str) or tool_name not in allowed_tools):
        return _err("VALIDATION_ERROR", "tool_name must be one of the allowed enums")
    if status is not None and (not isinstance(status, str) or status not in allowed_status):
        return _err("VALIDATION_ERROR", "status must be one of: received, fulfilled, rejected, error")
    if api_key_id is not None and (not isinstance(api_key_id, str) or not api_key_id.strip()):
        return _err("VALIDATION_ERROR", "api_key_id must be a non-empty string")
    if matched_template_id is not None and (not isinstance(matched_template_id, str) or not matched_template_id.strip()):
        return _err("VALIDATION_ERROR", "matched_template_id must be a non-empty string")

    def _parse_iso(s):
        if s is None:
            return None
        if not isinstance(s, str) or not s.strip():
            raise ValueError("bad datetime")
        # accept trailing Z
        ss = s.strip()
        if ss.endswith("Z"):
            ss = ss[:-1]
        return datetime.datetime.fromisoformat(ss)

    try:
        dt_from = _parse_iso(created_from)
    except ValueError:
        return _err("VALIDATION_ERROR", "created_from must be ISO 8601 date-time")
    try:
        dt_to = _parse_iso(created_to)
    except ValueError:
        return _err("VALIDATION_ERROR", "created_to must be ISO 8601 date-time")

    if page is None:
        page = 1
    if page_size is None:
        page_size = 20
    if sort_order is None:
        sort_order = "desc"

    if not isinstance(page, int) or page < 1:
        return _err("VALIDATION_ERROR", "page must be an integer >= 1")
    if not isinstance(page_size, int) or page_size < 1 or page_size > 100:
        return _err("VALIDATION_ERROR", "page_size must be an integer between 1 and 100")
    if not isinstance(sort_order, str) or sort_order not in ["asc", "desc"]:
        return _err("VALIDATION_ERROR", "sort_order must be 'asc' or 'desc'")

    # ---- ambient auth: choose a usable active api key + active workspace ----
    api_keys = _load("api_keys.json")
    workspaces = _load("workspaces.json")
    ws_by_id = {w.get("id"): w for w in workspaces if isinstance(w, dict) and w.get("id")}
    usable_key = None
    for k in api_keys:
        if not isinstance(k, dict):
            continue
        if k.get("status") != "active":
            continue
        ws = ws_by_id.get(k.get("workspace_id"))
        if ws and ws.get("status") == "active":
            usable_key = k
            break
    if not usable_key:
        return _err("UNAUTHORIZED", "API key or workspace disabled", error_code="AUTH_DISABLED")

    workspace_id = usable_key.get("workspace_id")
    caller_api_key_id = usable_key.get("id")

    # ---- quota + rate limit (reads count too) ----
    quota = _load("quota_counters.json")
    def _floor_minute(dt):
        return dt.replace(second=0, microsecond=0)
    def _floor_day(dt):
        return dt.replace(hour=0, minute=0, second=0, microsecond=0)
    dt_now = datetime.datetime.utcnow()
    minute_start = _floor_minute(dt_now).isoformat() + "Z"
    day_start = _floor_day(dt_now).isoformat() + "Z"

    def _get_counter(window_type, window_start):
        for row in quota:
            if isinstance(row, dict) and row.get("api_key_id") == caller_api_key_id and row.get("window_type") == window_type and row.get("window_start") == window_start:
                return row
        return None

    minute_ctr = _get_counter("minute", minute_start)
    day_ctr = _get_counter("day", day_start)
    if minute_ctr is None:
        minute_ctr = {
            "id": "qc_" + uuid.uuid4().hex,
            "api_key_id": caller_api_key_id,
            "window_type": "minute",
            "window_start": minute_start,
            "request_count": 0,
            "rejected_count": 0,
            "created_at": now,
            "updated_at": now,
        }
        quota.append(minute_ctr)
    if day_ctr is None:
        day_ctr = {
            "id": "qc_" + uuid.uuid4().hex,
            "api_key_id": caller_api_key_id,
            "window_type": "day",
            "window_start": day_start,
            "request_count": 0,
            "rejected_count": 0,
            "created_at": now,
            "updated_at": now,
        }
        quota.append(day_ctr)

    rate_limit = usable_key.get("rate_limit_per_min")
    daily_quota = usable_key.get("daily_request_quota")
    if not isinstance(rate_limit, int) or rate_limit < 1 or rate_limit > 6000:
        return _err("VALIDATION_ERROR", "API key has invalid rate_limit_per_min in store")
    if not isinstance(daily_quota, int) or daily_quota < 0 or daily_quota > 1000000:
        return _err("VALIDATION_ERROR", "API key has invalid daily_request_quota in store")

    would_minute = int(minute_ctr.get("request_count", 0)) + 1
    if would_minute > rate_limit:
        minute_ctr["request_count"] = would_minute
        minute_ctr["rejected_count"] = int(minute_ctr.get("rejected_count", 0)) + 1
        minute_ctr["updated_at"] = now

        would_day = int(day_ctr.get("request_count", 0)) + 1
        day_ctr["request_count"] = would_day
        day_ctr["rejected_count"] = int(day_ctr.get("rejected_count", 0)) + 1
        day_ctr["updated_at"] = now
        _save("quota_counters.json", quota)

        return _err("RATE_LIMIT", "Rate limit exceeded")

    would_day = int(day_ctr.get("request_count", 0)) + 1
    if daily_quota > 0 and would_day > daily_quota:
        minute_ctr["request_count"] = would_minute
        minute_ctr["rejected_count"] = int(minute_ctr.get("rejected_count", 0)) + 1
        minute_ctr["updated_at"] = now

        day_ctr["request_count"] = would_day
        day_ctr["rejected_count"] = int(day_ctr.get("rejected_count", 0)) + 1
        day_ctr["updated_at"] = now
        _save("quota_counters.json", quota)

        return _err("QUOTA_EXCEEDED", "Daily request quota exceeded")

    minute_ctr["request_count"] = would_minute
    minute_ctr["updated_at"] = now
    day_ctr["request_count"] = would_day
    day_ctr["updated_at"] = now
    _save("quota_counters.json", quota)

    # ---- enforce active workspace/key (explicit for this tool) ----
    ws = ws_by_id.get(workspace_id)
    if not ws or ws.get("status") != "active" or usable_key.get("status") != "active":
        return _err("UNAUTHORIZED", "API key or workspace disabled", error_code="AUTH_DISABLED")

    # ---- query ----
    rows = _load("suggestion_requests.json")
    out = []
    for r in rows:
        if not isinstance(r, dict):
            continue
        if r.get("workspace_id") != workspace_id:
            continue
        if tool_name is not None and r.get("tool_name") != tool_name:
            continue
        if status is not None and r.get("status") != status:
            continue
        if api_key_id is not None and r.get("api_key_id") != api_key_id:
            continue
        if matched_template_id is not None and r.get("matched_template_id") != matched_template_id:
            continue

        if dt_from is not None or dt_to is not None:
            ca = r.get("created_at")
            if not isinstance(ca, str):
                continue
            try:
                ca_dt = _parse_iso(ca)
            except ValueError:
                continue
            if dt_from is not None and ca_dt < dt_from:
                continue
            if dt_to is not None and ca_dt > dt_to:
                continue
        out.append(r)

    def _sort_key(rr):
        ca = rr.get("created_at")
        return ca if isinstance(ca, str) else ""
    out.sort(key=_sort_key, reverse=(sort_order == "desc"))

    total = len(out)
    start = (page - 1) * page_size
    end = start + page_size
    page_items = out[start:end]
    has_more = end < total

    # update api_key last_used_at for successful read
    for k in api_keys:
        if isinstance(k, dict) and k.get("id") == caller_api_key_id:
            k["last_used_at"] = now
            k["updated_at"] = now
            break
    _save("api_keys.json", api_keys)

    return {
        "data": page_items,
        "meta": {
            "page": page,
            "page_size": page_size,
            "total": total,
            "has_more": has_more
        }
    }
